create schema if not exists ingest;

create table if not exists ingest.visa_pathways (
  id bigint generated by default as identity primary key,
  country_code text not null check (country_code ~ '^[A-Z]{2}$'),
  country_name text not null,
  visa_name text not null,
  kind text not null check (kind in ('Study', 'Work', 'Working holiday', 'Skilled', 'Family', 'Temporary')),
  note text not null,
  authority text not null,
  source_url text not null check (source_url ~ '^https://'),
  source_title text not null,
  last_verified_on date not null,
  display_order integer not null default 0 check (display_order >= 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (country_code, visa_name)
);

comment on table ingest.visa_pathways is
  'Verified navigation catalogue for the workspace /visas surface. Source facts remain controlled by the issuing authority.';
comment on column ingest.visa_pathways.last_verified_on is
  'Date the official issuing-authority page was reviewed for catalogue inclusion.';

