on conflict (country_code, visa_name) do update
set country_name = excluded.country_name,
    kind = excluded.kind,
    note = excluded.note,
    authority = excluded.authority,
    source_url = excluded.source_url,
    source_title = excluded.source_title,
    last_verified_on = excluded.last_verified_on,
    display_order = excluded.display_order,
    is_active = excluded.is_active,
    updated_at = now();

create or replace view public.visa_pathways as
select id, country_code, country_name, visa_name, kind, note, authority,
       source_url, source_title, last_verified_on, display_order, updated_at
from ingest.visa_pathways
where is_active;

comment on view public.visa_pathways is
  'Read-only public catalogue consumed by the workspace /visas page.';

grant select on public.visa_pathways to anon, authenticated;
grant select, insert, update, delete on ingest.visa_pathways to service_role;
revoke all on ingest.visa_pathways from anon, authenticated;;
